-- Default-off normal-stage handoff. It is not provider proof or a scheduler.
CREATE TABLE IF NOT EXISTS continuous_normal_notice_handoffs (
 operation_token TEXT PRIMARY KEY,
 spreadsheet_id TEXT NOT NULL,
 epoch_id TEXT NOT NULL,
 expense_id TEXT NOT NULL,
 source_version INTEGER NOT NULL CHECK(source_version>0),
 projection TEXT NOT NULL CHECK(projection IN ('DAILY','EXPENSE_RAW','DETAIL','FINAL','PUBLICATION')),
 journal_entity TEXT NOT NULL,
 operation_kind TEXT NOT NULL CHECK(operation_kind IN ('CONFIRM','CANCEL')),
 created_at TEXT NOT NULL
);
CREATE TRIGGER IF NOT EXISTS continuous_normal_notice_handoff_insert BEFORE INSERT ON continuous_normal_notice_handoffs
WHEN NOT EXISTS (SELECT 1 FROM stable_workbook_claims c JOIN stable_recovery_epochs e ON e.epoch_id=NEW.epoch_id AND e.spreadsheet_id=c.spreadsheet_id JOIN stable_recovery_operations o ON o.epoch_id=e.epoch_id AND o.operation_token=c.operation_token JOIN sync_jobs j ON j.entity_type='EXPENSE' AND j.entity_key=e.target_key AND j.entity_version=e.target_version JOIN expense_events src ON src.expense_id=j.entity_key AND src.version=j.entity_version WHERE c.spreadsheet_id=NEW.spreadsheet_id AND c.operation_token=NEW.operation_token AND c.state='HELD' AND c.notice_stamp IS NOT NULL AND c.notice_identity IS NOT NULL AND e.state='ARMED' AND e.target_type='EXPENSE' AND e.target_key=NEW.expense_id AND e.target_version=NEW.source_version AND o.state='ADMITTED' AND j.status='PENDING' AND j.lease_token IS NULL AND j.lease_until IS NULL AND ((NEW.projection='PUBLICATION' AND NEW.operation_kind=CASE WHEN src.status='CANCELLED' THEN 'CANCEL' ELSE 'CONFIRM' END AND j.last_error=CASE NEW.operation_kind WHEN 'CONFIRM' THEN 'STABLE_STAGE_CONTINUE' ELSE 'STABLE_CANCELLATION_STAGE_CONTINUE' END AND EXISTS(SELECT 1 FROM continuous_publication_intents i JOIN continuous_publication_markers m ON m.spreadsheet_id=i.spreadsheet_id AND m.entity_id=i.entity_id AND m.sheet_id=i.sheet_id AND m.sheet_name=i.sheet_name AND m.row_number=i.row_number AND m.transition_id=i.transition_id AND m.version=i.source_version AND m.marker=i.after_value JOIN stable_source_revision r ON r.singleton=1 AND r.revision=i.source_revision WHERE i.transition_id=NEW.journal_entity AND i.spreadsheet_id=NEW.spreadsheet_id AND i.entity_id=NEW.expense_id AND i.source_version=NEW.source_version AND i.claim_token=NEW.operation_token AND i.state='VERIFIED' AND ((i.kind IN ('STAGE','PUBLISH') AND NEW.operation_kind='CONFIRM' AND src.status='CONFIRMED') OR (i.kind='REVOKE' AND NEW.operation_kind='CANCEL' AND src.status='CANCELLED')) AND m.state=CASE i.kind WHEN 'STAGE' THEN 'STAGED' WHEN 'PUBLISH' THEN 'PUBLISHED' ELSE 'REVOKED' END)) OR (NEW.projection='FINAL' AND j.last_error='STABLE_FINAL_NOTICE_PENDING' AND EXISTS(SELECT 1 FROM continuous_final_notice_evidence z WHERE z.operation_token=NEW.operation_token AND z.spreadsheet_id=NEW.spreadsheet_id AND z.epoch_id=NEW.epoch_id AND z.expense_id=NEW.expense_id AND z.source_version=NEW.source_version AND z.operation_kind=NEW.operation_kind)) OR (NEW.operation_kind='CONFIRM' AND src.status='CONFIRMED' AND j.last_error='STABLE_STAGE_CONTINUE' AND EXISTS(SELECT 1 FROM stable_projection_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.operation_token=NEW.operation_token AND p.entity_type='EXPENSE' AND p.entity_id=NEW.journal_entity AND p.projection=NEW.projection AND p.source_version=NEW.source_version AND p.state='VERIFIED')) OR (NEW.operation_kind='CANCEL' AND src.status='CANCELLED' AND j.last_error='STABLE_CANCELLATION_STAGE_CONTINUE' AND EXISTS(SELECT 1 FROM stable_expense_cancellation_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.operation_token=NEW.operation_token AND p.entity_type='EXPENSE' AND p.entity_id=NEW.journal_entity AND p.projection=NEW.projection AND p.cancellation_version=NEW.source_version AND p.state='VERIFIED')))) OR (SELECT count(*) FROM stable_projection_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.operation_token=NEW.operation_token)+(SELECT count(*) FROM stable_expense_cancellation_writes p WHERE p.spreadsheet_id=NEW.spreadsheet_id AND p.operation_token=NEW.operation_token)<>CASE WHEN NEW.projection IN ('FINAL','PUBLICATION') THEN 0 ELSE 1 END
BEGIN SELECT RAISE(ABORT,'normal notice handoff requires exact verified operation'); END;
CREATE TRIGGER IF NOT EXISTS continuous_normal_notice_handoff_no_update BEFORE UPDATE ON continuous_normal_notice_handoffs BEGIN SELECT RAISE(ABORT,'normal notice handoff immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_normal_notice_handoff_no_delete BEFORE DELETE ON continuous_normal_notice_handoffs BEGIN SELECT RAISE(ABORT,'normal notice handoff retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_normal_notice_handoff_no_replace BEFORE INSERT ON continuous_normal_notice_handoffs WHEN EXISTS(SELECT 1 FROM continuous_normal_notice_handoffs h WHERE h.operation_token=NEW.operation_token OR h.rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'normal notice handoff already exists'); END;
